CREATE TABLE "tenants" ("id" varchar PRIMARY KEY NOT NULL, "name" varchar(255) NOT NULL, "slug" varchar(100) NOT NULL, "code" varchar(9) NOT NULL, "plan" varchar NOT NULL DEFAULT ('free'), "settings" text DEFAULT ('{}'), "created_at" datetime NOT NULL DEFAULT (datetime('now')), "updated_at" datetime NOT NULL DEFAULT (datetime('now')), "deleted_at" datetime, CONSTRAINT "UQ_2310ecc5cb8be427097154b18fc" UNIQUE ("slug"), CONSTRAINT "UQ_3021c18db2b363ae9324c826c5a" UNIQUE ("code"));
CREATE TABLE "users" ("id" varchar PRIMARY KEY NOT NULL, "tenant_id" varchar, "email" varchar(50) NOT NULL, "password_hash" varchar(255), "first_name" varchar(20), "last_name" varchar(20), "avatar_url" text, "is_email_verified" boolean NOT NULL DEFAULT (0), "verification_token" varchar(255), "verification_otp" varchar(6), "verification_expires_at" datetime, "workspace_role" varchar NOT NULL DEFAULT ('member'), "isActive" boolean DEFAULT (1), "created_at" datetime NOT NULL DEFAULT (datetime('now')), "updated_at" datetime NOT NULL DEFAULT (datetime('now')), "deleted_at" datetime);
CREATE INDEX "IDX_97672ac88f789774dd47f7c8be" ON "users" ("email") ;
CREATE UNIQUE INDEX "IDX_8f438641d1d4a8af79152fc84a" ON "users" ("verification_token") WHERE verification_token IS NOT NULL;
CREATE UNIQUE INDEX "IDX_e9f4c2efab52114c4e99e28efb" ON "users" ("tenant_id", "email") ;
CREATE TABLE "sessions" ("id" varchar PRIMARY KEY NOT NULL, "user_id" varchar NOT NULL, "status" varchar(10) NOT NULL DEFAULT ('ACTIVE'), "device_name" varchar(255), "browser" varchar(100), "operating_system" varchar(100), "ip_address" varchar, "user_agent" text, "revoked_at" datetime, "last_used_at" datetime NOT NULL DEFAULT (CURRENT_TIMESTAMP), "expires_at" datetime NOT NULL, "created_at" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE "transactions" ("id" varchar PRIMARY KEY NOT NULL, "payment_id" varchar NOT NULL, "user_id" varchar NOT NULL, "tenant_id" varchar, "type" varchar NOT NULL, "amount" bigint NOT NULL, "currency" varchar(3) NOT NULL, "description" text, "created_at" datetime NOT NULL DEFAULT (datetime('now')), "updated_at" datetime NOT NULL DEFAULT (datetime('now')));
CREATE INDEX "IDX_e9acc6efa76de013e8c1553ed2" ON "transactions" ("user_id") ;
CREATE TABLE "payments" ("id" varchar PRIMARY KEY NOT NULL, "user_id" varchar NOT NULL, "order_id" varchar NOT NULL, "amount" bigint NOT NULL, "currency" varchar(3) NOT NULL, "status" varchar NOT NULL DEFAULT ('PENDING'), "paymentMethod" varchar NOT NULL, "razorpay_payment_id" varchar(255), "razorpay_signature" varchar(512), "created_at" datetime NOT NULL DEFAULT (datetime('now')), "updated_at" datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT "REL_b2f7b823a21562eeca20e72b00" UNIQUE ("order_id"));
CREATE INDEX "IDX_e7d1bec5311dcddd28c50547e8" ON "payments" ("razorpay_payment_id") ;
CREATE INDEX "IDX_c2a89b63635ae2b4cc76f17a08" ON "payments" ("user_id", "status") ;
CREATE TABLE "orders" ("id" varchar PRIMARY KEY NOT NULL, "user_id" varchar NOT NULL, "tenant_id" varchar, "amount" bigint NOT NULL, "currency" varchar(3) NOT NULL, "status" varchar NOT NULL DEFAULT ('PENDING'), "razorpay_order_id" varchar(255), "plan" varchar(100), "created_at" datetime NOT NULL DEFAULT (datetime('now')), "updated_at" datetime NOT NULL DEFAULT (datetime('now')));
CREATE INDEX "IDX_a922b820eeef29ac1c6800e826" ON "orders" ("user_id") ;
CREATE INDEX "IDX_a493914f314964159c6fb6fe5f" ON "orders" ("razorpay_order_id") ;
CREATE TABLE "subscriptions" ("id" varchar PRIMARY KEY NOT NULL, "user_id" varchar NOT NULL, "tenant_id" varchar, "plan" varchar NOT NULL, "status" varchar NOT NULL DEFAULT ('ACTIVE'), "current_period_start" datetime NOT NULL, "current_period_end" datetime NOT NULL, "cancel_at_period_end" boolean NOT NULL DEFAULT (0), "created_at" datetime NOT NULL DEFAULT (datetime('now')), "updated_at" datetime NOT NULL DEFAULT (datetime('now')));
CREATE INDEX "IDX_d0a95ef8a28188364c546eb65c" ON "subscriptions" ("user_id") ;
